            // Generate branch
            for (num l = 0; l < branchLength; l = l + 1) {
                block(l*dx+ox, l*dy+oy, l*dz+oz, branchBlock);
            }
            // Rotate angle of next branch
            branchAngle = branchAngle + goldenAngle;
        }
    }
    block(0, i, 0, trunkBlock);
}

for (num b = 1; b <= topBranches; b = b + 1) {
    num t = b/topBranches;
    num ti = 1-t;
    // Branch direction vector
    num dx = sin(branchAngle) * t;
    num dy = topBranchVerticalDirection;
    num dz = cos(branchAngle) * t;
    // Normalize vector
    num mag = sqrt(pow(dx,2)+pow(dy,2)+pow(dz,2));
    dx = dx/mag;
    dy = dy/mag;
    dz = dz/mag;
    // Branch origin
    num ox = 0;
    num oy = trunkHeight;
    num oz = 0;
    // Set branch block based on largest unsigned vector component
    str branchBlock = topBranchBlockY;
    if (abs(dx) > max(abs(dy),abs(dz))) branchBlock = topBranchBlockX;
    else if (abs(dz) > max(abs(dy),abs(dx))) branchBlock = topBranchBlockZ;
    num branchLength = topBranchLengthUpwardsMin*ti + topBranchLengthOutwardsMin*t;
    // Generate branch
    for (num l = 0; l < branchLength; l = l + 1) {
        block(l*dx+ox, l*dy+oy, l*dz+oz, branchBlock);
    }
    // Rotate angle of next branch
    branchAngle = branchAngle + goldenAngle;
}

stalactite.script:
num height = randomInt(4) + 1;

bool doMerge = false;

for(num i = 0; i > -height; i = i - 1) {
    str blockID = getBlock(0,i,0);
    if(blockID == "minecraft:pointed_dripstone") {
        height = -i;
        doMerge = true;
    } else if(blockID != "minecraft:air") fail;
}

for(num i = 0; i > -height; i = i - 1) {
    if(i == 0 && height > 2) {
		if(getBlock(1,i+2,0) != "minecraft:air" && 
		   getBlock(-1,i+2,0) != "minecraft:air" && 
		   getBlock(0,i+2,1) != "minecraft:air" && 
		   getBlock(0,i+2,-1) != "minecraft:air" && 
			getBlock(1,i+2,0) != "minecraft:pointed_dripstone" && 
		   getBlock(-1,i+2,0) != "minecraft:pointed_dripstone" && 
		   getBlock(0,i+2,1) != "minecraft:pointed_dripstone" && 
		   getBlock(0,i+2,-1) != "minecraft:pointed_dripstone") block(0,i+2,0,"minecraft:lava");
		block(0,i,0,"minecraft:pointed_dripstone[vertical_direction=down,thickness=base]");
	}
    else if((i == -height+1) && doMerge) {
        block(0,i,0,"minecraft:pointed_dripstone[vertical_direction=down,thickness=tip_merge]");
        block(0,i-1,0,"minecraft:pointed_dripstone[vertical_direction=up,thickness=tip_merge]");
    } else if(i == -height+1) {
		block(0,i,0,"minecraft:pointed_dripstone[vertical_direction=down,thickness=tip]");
    } else if(i == -height+2) {
		block(0,i,0,"minecraft:pointed_dripstone[vertical_direction=down,thickness=frustum]");
    } else {
		block(0,i,0,"minecraft:pointed_dripstone[vertical_direction=down,thickness=middle]");
	}
}

stalagmite.script:
num height = randomInt(4) + 1;

bool doMerge = false;

for(num i = 0; i < height; i = i + 1) {
    str blockID = getBlock(0,i,0);
    if(blockID == "minecraft:pointed_dripstone") {
        height = i;
        doMerge = true;
    } else if(blockID != "minecraft:air") fail;
}

for(num i = 0; i < height; i = i + 1) {
    if(i == 0 && height > 2) block(0,i,0,"minecraft:pointed_dripstone[vertical_direction=up,thickness=base]");
    else if((i == height-1) && doMerge) {
        block(0,i,0,"minecraft:pointed_dripstone[vertical_direction=up,thickness=tip_merge]");
        block(0,i+1,0,"minecraft:pointed_dripstone[vertical_direction=down,thickness=tip_merge]");
    } else if(i == height-1) block(0,i,0,"minecraft:pointed_dripstone[vertical_direction=up,thickness=tip]");
    else if(i == height-2) block(0,i,0,"minecraft:pointed_dripstone[vertical_direction=up,thickness=frustum]");
    else block(0,i,0,"minecraft:pointed_dripstone[vertical_direction=up,thickness=middle]");
}

